"""Generates seal-vectors.json: the push and reply seal test vectors
(PROTOCOL.md "Sealed pushes and the reply mailbox") with Python's
`cryptography`, an implementation independent of hostd (Rust) and the phone
(CryptoKit). Both test against the file it writes.

    python3 gen_seal_vectors.py > seal-vectors.json

ECDSA signatures are randomized: the file holds one signature per message
that every side must verify, not reproduce.
"""
import base64
import hashlib
import json

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF

N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551


def scalar(label):
    return hashlib.sha256(label.encode()).digest()


def key(s):
    return ec.derive_private_key(int.from_bytes(s, "big"), ec.SECP256R1())


def pub(k):
    return k.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)


def hkdf(ikm, salt, info):
    return HKDF(algorithm=hashes.SHA256(), length=32, salt=salt, info=info).derive(ikm)


def box_scalar(identity):
    info = b"cmux-mobile-mac-box-v1"
    out = hkdf(identity, b"", info)
    counter = 0
    while not (0 < int.from_bytes(out, "big") < N):
        counter += 1
        out = hkdf(identity, b"", info + bytes([counter]))
    return out


def context(domain, *parts):
    return b"\0".join([domain.encode()] + [p.encode() for p in parts])


def seal(recipient_pub_bytes, ctx, plaintext, eph_scalar, nonce):
    eph = key(eph_scalar)
    recipient = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), recipient_pub_bytes)
    z = eph.exchange(ec.ECDH(), recipient)
    k = hkdf(z, pub(eph) + recipient_pub_bytes, ctx)
    ct = AESGCM(k).encrypt(nonce, plaintext, ctx)
    return base64.urlsafe_b64encode(b"\x01" + pub(eph) + nonce + ct).rstrip(b"=").decode()


def sign(k, message):
    r, s = decode_dss_signature(k.sign(message, ec.ECDSA(hashes.SHA256())))
    return (r.to_bytes(32, "big") + s.to_bytes(32, "big")).hex()


def canonical(v):
    if isinstance(v, dict):
        return "{" + ",".join(canonical_str(k) + ":" + canonical(v[k]) for k in sorted(v, key=lambda k: k.encode())) + "}"
    if isinstance(v, list):
        return "[" + ",".join(canonical(x) for x in v) + "]"
    if isinstance(v, bool):
        return "true" if v else "false"
    if v is None:
        return "null"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return canonical_str(v)
    raise TypeError(v)


def canonical_str(s):
    out = '"'
    for c in s:
        if c == '"':
            out += '\\"'
        elif c == "\\":
            out += "\\\\"
        elif ord(c) < 0x20:
            out += {"\n": "\\n", "\r": "\\r", "\t": "\\t", "\b": "\\b", "\f": "\\f"}.get(c, "\\u%04x" % ord(c))
        else:
            out += c
    return out + '"'


mac = "6f1c2a7e-0b1d-4c55-9a43-2d8e5b7f3c10"
phone = "a2b4c6d8-1e3f-4a5b-8c7d-9e0f1a2b3c4d"
mac_identity = key(scalar("cmux-mobile test mac identity"))
mac_box = key(box_scalar(scalar("cmux-mobile test mac identity")))
phone_identity = key(scalar("cmux-mobile test phone identity"))
phone_push = key(scalar("cmux-mobile test phone push"))

event_id = "p-perm1"
push_plain = json.dumps({"v": 2, "mac": mac, "kind": "question", "eventId": event_id, "title": "Which branch?"},
                        separators=(",", ":")).encode()
push_ctx = context("cmux-mobile-push-seal-v1", mac, phone, event_id)
push_box = seal(pub(phone_push), push_ctx, push_plain, scalar("eph push"), bytes(range(12)))
push_sig_msg = context("cmux-mobile-push-v1", mac, phone, event_id, push_box)

reply_id = "0d9f5e2c-7b3a-4e61-8f20-5c4b3a291807"
reply = {
    "v": 1, "id": reply_id, "mac": mac, "phone": phone, "kind": "completed",
    "target": {"sessionId": "s1"}, "action": {"type": "text", "text": "ship it\n\"now\""},
    "nonce": "n0nce0123456789abcdef", "issuedAt": 1792540800, "expiresAt": 1792541100,
}
reply_canonical = canonical(reply)
reply_digest = hashlib.sha256(reply_canonical.encode()).hexdigest()
reply_sig_msg = context("cmux-mobile-reply-v1", mac, phone, reply_digest)
reply["sig"] = sign(phone_identity, reply_sig_msg)
reply_plain = json.dumps(reply, separators=(",", ":")).encode()
reply_ctx = context("cmux-mobile-reply-seal-v1", mac, phone, reply_id)
reply_box = seal(pub(mac_box), reply_ctx, reply_plain, scalar("eph reply"), bytes(range(12, 24)))

push_key_msg = context("cmux-mobile-push-key-v1", mac, phone, pub(phone_push).hex())
mac_box_msg = context("cmux-mobile-mac-box-v1", mac, pub(mac_box).hex())

print(json.dumps({
    "comment": "Generated by gen_seal_vectors.py (Python cryptography). ECDSA signatures are randomized: verify them, do not reproduce them.",
    "mac": mac,
    "phone": phone,
    "macIdentityScalar": scalar("cmux-mobile test mac identity").hex(),
    "macIdentityKey": pub(mac_identity).hex(),
    "macBoxScalar": box_scalar(scalar("cmux-mobile test mac identity")).hex(),
    "macBoxKey": pub(mac_box).hex(),
    "macBoxMessage": mac_box_msg.hex(),
    "macBoxSignature": sign(mac_identity, mac_box_msg),
    "phoneIdentityScalar": scalar("cmux-mobile test phone identity").hex(),
    "phoneIdentityKey": pub(phone_identity).hex(),
    "phonePushScalar": scalar("cmux-mobile test phone push").hex(),
    "phonePushKey": pub(phone_push).hex(),
    "pushKeyMessage": push_key_msg.hex(),
    "pushKeySignature": sign(phone_identity, push_key_msg),
    "push": {
        "eventId": event_id,
        "context": push_ctx.hex(),
        "ephemeralScalar": scalar("eph push").hex(),
        "nonce": bytes(range(12)).hex(),
        "plaintext": push_plain.decode(),
        "box": push_box,
        "signatureMessage": push_sig_msg.hex(),
        "signature": sign(mac_identity, push_sig_msg),
    },
    "reply": {
        "id": reply_id,
        "context": reply_ctx.hex(),
        "ephemeralScalar": scalar("eph reply").hex(),
        "nonce": bytes(range(12, 24)).hex(),
        "canonical": reply_canonical,
        "digest": reply_digest,
        "signatureMessage": reply_sig_msg.hex(),
        "plaintext": reply_plain.decode(),
        "box": reply_box,
    },
}, indent=2))
